(function () {
  'use strict';
  var store=window.TradeJournalStrategyEducationStore;
  var i18n=window.TradeJournalStrategyEducationI18n;
  var config=window.TradeJournalPatternAIConfig||{};
  var baseUrl=String(config.baseUrl||'').replace(/\/$/,'');
  function uid(){return store.uid('strategy-proposal');}
  function request(path,payload){var controller=new AbortController(),timer=setTimeout(function(){controller.abort();},60000);return fetch(baseUrl+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal}).then(function(response){if(!response.ok)return response.json().catch(function(){return{};}).then(function(body){throw new Error(body.error||'AI_REQUEST_FAILED');});return response.json();}).finally(function(){clearTimeout(timer);});}
  function fileMeta(items){return (items||[]).map(function(file){return{fileName:file.fileName,mimeType:file.mimeType,note:file.note||''};});}
  function context(record){var p=record.positionManagement,r=record.riskManagement,o=record.overallFramework;return {id:record.id,positionManagement:{entryRules:p.entryRules,stopLossRules:p.stopLossRules,exitTargetRules:p.exitTargetRules,positionSizingRules:p.positionSizingRules,freeNotes:p.freeNotes,attachments:fileMeta(p.attachments)},riskManagement:{maxRiskPerTradePercent:r.maxRiskPerTradePercent,dailyDrawdownLimitPercent:r.dailyDrawdownLimitPercent,totalDrawdownLimitPercent:r.totalDrawdownLimitPercent,maxConcurrentTrades:r.maxConcurrentTrades,maxProfitCapPerTrade:r.maxProfitCapPerTrade,freeNotes:r.freeNotes,attachments:fileMeta(r.attachments)},overallFramework:{description:o.description,attachments:fileMeta(o.attachments)},aiUnderstandingSummary:record.aiUnderstandingSummary,language:i18n.language()};}
  function normalizeDigits(value){var fa='۰۱۲۳۴۵۶۷۸۹',ar='٠١٢٣٤٥٦٧٨٩';return String(value||'').replace(/[۰-۹]/g,function(x){return fa.indexOf(x);}).replace(/[٠-٩]/g,function(x){return ar.indexOf(x);}).replace(/٫/g,'.');}
  function numeric(message,re){var match=normalizeDigits(message).match(re);return match?Number(match[1]):null;}
  function suggestion(path,value,section,mode){return{id:uid(),path:path,section:section,value:value,mode:mode||'append',status:'pending',createdAt:new Date().toISOString()};}
  function merged(record,path,message,replace){var current=String(store.getPath(record,path)||'').trim(),next=String(message||'').trim();return replace||!current?next:(current.indexOf(next)>-1?current:current+'\n'+next);}
  function localSuggestions(record,message){var text=normalizeDigits(message),lower=text.toLowerCase(),replace=/اصلاح|جایگزین|درستش|اشتباه|replace|correct|بدلاً|تصحيح|reemplaz/i.test(lower),out=[];function addText(path,section,re){if(re.test(lower))out.push(suggestion(path,merged(record,path,message,replace),section,replace?'replace':'append'));}
    var value=numeric(text,/(?:ریسک(?:م| هر معامله)?|risk(?: per trade)?|مخاطرة(?: لكل صفقة)?|riesgo(?: por operación)?)\D{0,18}(\d+(?:\.\d+)?)/i);if(value!==null)out.push(suggestion('riskManagement.maxRiskPerTradePercent',value,'riskManagement','replace'));
    value=numeric(text,/(?:(?:افت|drawdown|تراجع).{0,12}(?:روزانه|daily|يومي|diario)|(?:روزانه|daily|يومي|diario).{0,12}(?:افت|drawdown|تراجع))\D{0,12}(\d+(?:\.\d+)?)/i);if(value!==null)out.push(suggestion('riskManagement.dailyDrawdownLimitPercent',value,'riskManagement','replace'));
    value=numeric(text,/(?:(?:افت|drawdown|تراجع).{0,12}(?:کل|total|كلي)|(?:کل|total|كلي).{0,12}(?:افت|drawdown|تراجع))\D{0,12}(\d+(?:\.\d+)?)/i);if(value!==null)out.push(suggestion('riskManagement.totalDrawdownLimitPercent',value,'riskManagement','replace'));
    value=numeric(text,/(?:حداکثر|maximum|max|أقصى|máximo).{0,18}(?:معامل|trade|صفق|operacion)\D{0,10}(\d+)/i);if(value!==null)out.push(suggestion('riskManagement.maxConcurrentTrades',value,'riskManagement','replace'));
    value=numeric(text,/(?:سقف سود|profit cap|سقف الربح|tope de beneficio)\D{0,18}(\d+(?:\.\d+)?)/i);if(value!==null)out.push(suggestion('riskManagement.maxProfitCapPerTrade',value,'riskManagement','replace'));
    addText('positionManagement.stopLossRules','positionManagement',/استاپ|حد ضرر|breakeven|break even|trailing|وقف الخسارة|تعادل|stop loss/i);
    addText('positionManagement.entryRules','positionManagement',/ورود|entry|confluence|تایید|تأیید|دخول|entrada|confirm/i);
    addText('positionManagement.exitTargetRules','positionManagement',/خروج|تارگت|هدف|rrr|partial|take profit|exit|salida/i);
    addText('positionManagement.positionSizingRules','positionManagement',/حجم|سایز|position siz|حجم الصفقة|tamaño/i);
    addText('overallFramework.description','overallFramework',/amd|فلسفه|چارچوب|سشن محور|framework|philosoph|إطار|فلسفة|marco/i);
    var unique={};return out.filter(function(item){if(unique[item.path])return false;unique[item.path]=true;return true;});
  }
  function localReply(suggestions){var lang=i18n.language(),count=suggestions.length;if(lang==='fa')return count?'متوجه شدم. '+i18n.number(count)+' تغییر را برای بررسی شما آماده کردم؛ هیچ‌کدام بدون تأیید اعمال نمی‌شوند.':'این نکته را در زمینه کامل استراتژی نگه می‌دارم. اگر یک قانون عددی یا اجرایی مشخص کنید، آن را به‌صورت پیشنهاد قابل تأیید نمایش می‌دهم.';if(lang==='ar')return count?'فهمت. أعددت '+i18n.number(count)+' تحديثات للمراجعة ولن تُطبّق دون موافقتك.':'سأحتفظ بهذه الملاحظة ضمن سياق الاستراتيجية.';if(lang==='es')return count?'Entendido. Preparé '+count+' cambios para revisar; no se aplicarán sin tu aprobación.':'Mantendré esta nota en el contexto completo de la estrategia.';return count?'Understood. I prepared '+count+' field updates for review; none will apply without your approval.':'I will keep this note in the full strategy context.';}
  function normalizeSuggestion(item){var path=String(item.path||''),section=path.split('.')[0];if((window.TradeJournalStrategyEducationTypes.textPaths||[]).concat(window.TradeJournalStrategyEducationTypes.numericPaths||[]).indexOf(path)<0)return null;var numeric=(window.TradeJournalStrategyEducationTypes.numericPaths||[]).indexOf(path)>-1;return suggestion(path,numeric?(item.value===''?null:Number(item.value)):String(item.value||''),section,item.mode==='replace'?'replace':'append');}
  async function payload(record){var value=context(record);value.attachments=await store.attachmentsForAI(record);return value;}
  async function chat(record,message){var value=await payload(record);value.message=message;value.chatHistory=(record.chatHistory||[]).slice(-24).map(function(item){return{role:item.role,content:item.content};});try{var result=await request('/api/strategy-education/chat',value);return{reply:String(result.reply||''),summary:result.summary||null,suggestions:(result.suggestions||[]).map(normalizeSuggestion).filter(Boolean),provider:result.provider||'openai',local:false};}catch(error){var suggestions=localSuggestions(record,message);return{reply:localReply(suggestions),summary:store.localSummary(record),suggestions:suggestions,provider:'local-fallback',local:true,error:error};}}
  async function summarize(record){var value=await payload(record);try{var result=await request('/api/strategy-education/summarize',value);return{summary:result.summary||store.localSummary(record),provider:result.provider||'openai',local:false};}catch(error){return{summary:store.localSummary(record),provider:'local-fallback',local:true,error:error};}}
  async function proposeFromEvent(narrative,images){var value={narrative:String(narrative||''),images:images||[],language:i18n.language()};try{var result=await request('/api/strategy-education/from-event',value);return{proposal:result.proposal,provider:result.provider||'openai',local:false};}catch(error){var copy={fa:{name:'فرضیه رویداد بازار',framework:'این پیش‌نویس از روایت رویداد ساخته شده و باید با نمونه‌های بعدی تأیید یا رد شود.',validation:'این ساختار را در رخدادهای بعدی ثبت کن و نتیجه را confirmed یا invalidated علامت بزن.'},ar:{name:'فرضية حدث السوق',framework:'تم إنشاء هذه المسودة من وصف الحدث ويجب تأكيدها أو إبطالها بأمثلة لاحقة.',validation:'سجّل البنية في الأحداث القادمة وحدد النتيجة كمؤكدة أو ملغاة.'},es:{name:'Hipótesis del evento',framework:'Este borrador nace del evento descrito y debe confirmarse o invalidarse con casos posteriores.',validation:'Registra futuros casos y marca el resultado como confirmado o invalidado.'},en:{name:'Market event hypothesis',framework:'This draft was derived from the described event and must be confirmed or invalidated with future samples.',validation:'Record the structure in future events and mark each outcome confirmed or invalidated.'}}[i18n.language()]||{};return{proposal:{name:copy.name,overallFramework:copy.framework+'\n'+String(narrative||''),entryRules:'',stopLossRules:'',exitTargetRules:'',validationPlan:copy.validation,predictedOutcome:String(narrative||'').slice(0,220)},provider:'local-fallback',local:true,error:error};}}
  window.TradeJournalStrategyEducationAI={chat:chat,summarize:summarize,proposeFromEvent:proposeFromEvent,localSuggestions:localSuggestions};
}());
